// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func environmentScanMapperNullable(prefix string) scan.Mapper[*Environment] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Environment, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *environmentPreloadBuf) any
		}
		targets := make([]target, 0, 6)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *environmentPreloadBuf) any { return &b.ID }})
			case "team_id":
				targets = append(targets, target{i, func(b *environmentPreloadBuf) any { return &b.TeamID }})
			case "provider_environment_id":
				targets = append(targets, target{i, func(b *environmentPreloadBuf) any { return &b.ProviderEnvironmentID }})
			case "created_at":
				targets = append(targets, target{i, func(b *environmentPreloadBuf) any { return &b.CreatedAt }})
			case "deleted_at":
				targets = append(targets, target{i, func(b *environmentPreloadBuf) any { return &b.DeletedAt }})
			case "active_team_id":
				targets = append(targets, target{i, func(b *environmentPreloadBuf) any { return &b.ActiveTeamID }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(environmentPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Environment, error) {
				buf := link.(*environmentPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.Valid) &&
					!(buf.TeamID.Valid) &&
					!(buf.ProviderEnvironmentID.Valid) &&
					!(buf.CreatedAt.Valid) &&
					!(buf.DeletedAt.Valid) &&
					!(buf.ActiveTeamID.Valid) {
					return nil, nil
				}

				o := new(Environment)
				if buf.ID.Valid {
					o.ID = buf.ID.V
				}
				if buf.TeamID.Valid {
					o.TeamID = buf.TeamID.V
				}
				if buf.ProviderEnvironmentID.Valid {
					o.ProviderEnvironmentID = buf.ProviderEnvironmentID.V
				}
				if buf.CreatedAt.Valid {
					o.CreatedAt = buf.CreatedAt.V
				}
				o.DeletedAt = buf.DeletedAt
				o.ActiveTeamID = buf.ActiveTeamID
				return o, nil
			}
	}
}

func (o *Environment) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Instances":
		rels, ok := retrieved.(InstanceSlice)
		if !ok {
			return fmt.Errorf("environment cannot load %T as %q", retrieved, name)
		}

		o.R.Instances = rels
		o.R.Loaded.Instances = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Environment = o
				rel.R.Loaded.Environment = true
			}
		}
		return nil
	default:
		return fmt.Errorf("environment has no relationship %q", name)
	}
}

type environmentPreloader struct{}

func buildEnvironmentPreloader() environmentPreloader {
	return environmentPreloader{}
}

type environmentThenLoader[Q orm.Loadable] struct {
	Instances func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildEnvironmentThenLoader[Q orm.Loadable]() environmentThenLoader[Q] {
	type InstancesLoadInterface interface {
		LoadInstances(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return environmentThenLoader[Q]{
		Instances: thenLoadBuilder[Q](
			"Instances",
			func(ctx context.Context, exec bob.Executor, retrieved InstancesLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadInstances(ctx, exec, mods...)
			},
		),
	}
}

// LoadInstances loads the environment's Instances into the .R struct
func (o *Environment) LoadInstances(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Instances = nil
	o.R.Loaded.Instances = false

	related, err := o.Instances(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Environment = o
		rel.R.Loaded.Environment = true
	}

	o.R.Instances = related
	o.R.Loaded.Instances = true
	return nil
}

// LoadInstances loads the environment's Instances into the .R struct
func (os EnvironmentSlice) LoadInstances(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	instances, err := os.Instances(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Instances = nil
		o.R.Loaded.Instances = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	environmentByKey := make(map[string][]*Environment, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		environmentByKey[o.ID] = append(environmentByKey[o.ID], o)
	}

	for _, rel := range instances {

		owners, ok := environmentByKey[rel.EnvironmentID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.Environment = o
			rel.R.Loaded.Environment = true

			o.R.Instances = append(o.R.Instances, rel)

		}
	}

	return nil
}

// environmentC is where relationship counts are stored.
type environmentC struct {
	Instances *int64
}

// PreloadCount sets a count in the C struct by name
func (o *Environment) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Instances":
		o.C.Instances = &count
	}
	return nil
}

type environmentCountPreloader struct {
	Instances func(...bob.Mod[*dialect.SelectQuery]) mysql.Preloader
}

func buildEnvironmentCountPreloader() environmentCountPreloader {
	return environmentCountPreloader{
		Instances: func(mods ...bob.Mod[*dialect.SelectQuery]) mysql.Preloader {
			return countPreloader[*Environment]("Instances", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Environments.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(mysql.Raw("count(*)")),

					sm.From(Instances.NameAsExpr()),
					sm.Where(mysql.Quote(Instances.Alias(), "environment_id").EQ(mysql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return mysql.Group(mysql.Select(subqueryMods...).Expression)
			})
		},
	}
}

type environmentCountThenLoader[Q orm.Loadable] struct {
	Instances func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildEnvironmentCountThenLoader[Q orm.Loadable]() environmentCountThenLoader[Q] {
	type InstancesCountInterface interface {
		LoadCountInstances(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return environmentCountThenLoader[Q]{
		Instances: countThenLoadBuilder[Q](
			"Instances",
			func(ctx context.Context, exec bob.Executor, retrieved InstancesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountInstances(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountInstances loads the count of Instances into the C struct
func (o *Environment) LoadCountInstances(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.Instances(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.Instances = &count
	return nil
}

// LoadCountInstances loads the count of Instances for a slice in a single batch query
func (os EnvironmentSlice) LoadCountInstances(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs
	PKArgSlice := make([]bob.Expression, 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		PKArgSlice = append(PKArgSlice, mysql.Arg(o.ID))
	}
	PKArgExpr := mysql.Group(PKArgSlice...)

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    string
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			Instances.Columns.EnvironmentID.As("id"),
			mysql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(Instances.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(Instances.Columns.EnvironmentID.OP("IN", PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(Instances.Columns.EnvironmentID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		mysql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[string]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.Instances = &count
	}

	return nil
}

type environmentJoins[Q dialect.Joinable] struct {
	typ       string
	Instances modAs[Q, instanceColumns]
}

func (j environmentJoins[Q]) aliasedAs(alias string) environmentJoins[Q] {
	return buildEnvironmentJoins[Q](buildEnvironmentColumns(alias), j.typ)
}

func buildEnvironmentJoins[Q dialect.Joinable](cols environmentColumns, typ string) environmentJoins[Q] {
	return environmentJoins[Q]{
		typ: typ,
		Instances: modAs[Q, instanceColumns]{
			c: Instances.Columns,
			f: func(to instanceColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Instances.NameExpr().As(to.Alias())).On(
						to.EnvironmentID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
